"""Pure counting, tokenization, ordering, and result construction."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
import re


@dataclass(frozen=True, slots=True)
class TopWord:
    """A token and its number of occurrences."""

    word: str
    count: int


@dataclass(frozen=True, slots=True)
class WordStat:
    """Contract-exact statistics for decoded text."""

    lines: int
    words: int
    chars: int
    top: tuple[TopWord, ...]


def analyze_text(text: str, top_n: int = 3) -> WordStat:
    """Return the contracted statistics for already-decoded text."""

    tokens = re.findall(r"[a-z0-9]+", text.lower())
    counts = Counter(tokens)
    top = tuple(
        TopWord(word, count)
        for word, count in sorted(
            counts.items(), key=lambda item: (-item[1], item[0])
        )[:top_n]
    )

    return WordStat(
        lines=len(text.splitlines()),
        words=len(tokens),
        chars=len(text),
        top=top,
    )
